const SIGLA={'pt-BR':'BR'};
const CARPETA={en:'en',de:'de',fr:'fr',it:'it',pt:'pt','pt-BR':'pt-br',ru:'ru',zh:'zh',ja:'ja',ko:'ko'};
const BANDERA={es:'es',en:'us',de:'de',fr:'fr',it:'it',pt:'pt','pt-BR':'br',ru:'ru',zh:'cn',ja:'jp',ko:'kr'};
(function(){
  const els=[...document.querySelectorAll('[data-i18n]')];
  const arias=[...document.querySelectorAll('[data-i18n-aria]')];
  const orig=new Map(els.map(e=>[e,e.innerHTML]));
  const origAria=new Map(arias.map(e=>[e,e.getAttribute('aria-label')]));
  const origTitle=document.title;
  const esHome=document.body.dataset.page==='home';
  /* Páginas con versión propia por idioma (/en/, /de/…): el texto ya viene traducido en el HTML */
  const fija=document.documentElement.dataset.paginaIdioma,raiz=document.documentElement.dataset.raiz||'';
  const urlDe=l=>raiz+(l==='es'?'':CARPETA[l]+'/')+(location.pathname.split('/').pop()||'index.html')+(window.hashInicial||location.hash);
  const btn=document.querySelector('.lang-btn'),list=document.querySelector('.lang-list');
  const flag=btn.querySelector('.flag'),code=btn.querySelector('.code');
  list.innerHTML=Object.entries(IDIOMAS).map(([k,v],i)=>`<li role="option" tabindex="-1" data-l="${k}" lang="${k}" aria-label="${v}" title="${v}" style="--i:${i}"><span class="flag fi fis fi-${BANDERA[k]}"></span><b>${SIGLA[k]||k.toUpperCase()}</b></li>`).join('');list.hidden=false;
  const items=[...list.children];

  function aplicar(l){
    const d=T[l]||{};
    if(!fija)els.forEach(e=>{e.innerHTML=d[e.dataset.i18n]??orig.get(e)});
    arias.forEach(e=>e.setAttribute('aria-label',d[e.dataset.i18nAria]??origAria.get(e)));
    document.documentElement.dataset.idioma=l;document.documentElement.lang=l==='zh'?'zh-Hans':l==='en'?'en-US':l==='pt'?'pt-PT':l;
    if(!fija)document.title=esHome&&d.footer_tag?'FuentePatos — '+d.footer_tag:origTitle;
    flag.className='flag fi fis fi-'+BANDERA[l];code.textContent=SIGLA[l]||l.toUpperCase();
    items.forEach(i=>i.setAttribute('aria-selected',i.dataset.l===l));
  }
  function abrir(o){list.classList.toggle('open',o);btn.setAttribute('aria-expanded',o);if(o)(list.querySelector('[aria-selected=true]')||items[0]).focus()}
  function elegir(l){try{localStorage.setItem('idioma',l)}catch(e){}if(fija&&l!==fija){location.href=urlDe(l);return}aplicar(l);abrir(false);btn.focus()}

  btn.addEventListener('click',()=>abrir(!list.classList.contains('open')));
  list.addEventListener('click',e=>{const li=e.target.closest('li');if(li)elegir(li.dataset.l)});
  list.addEventListener('keydown',e=>{
    const i=items.indexOf(document.activeElement);
    if(e.key==='ArrowDown'){e.preventDefault();items[(i+1)%items.length].focus()}
    else if(e.key==='ArrowUp'){e.preventDefault();items[(i-1+items.length)%items.length].focus()}
    else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(i>=0)elegir(items[i].dataset.l)}
    else if(e.key==='Escape'){abrir(false);btn.focus()}
  });
  document.addEventListener('click',e=>{if(!e.target.closest('.lang'))abrir(false)});

  let l;
  try{l=new URLSearchParams(location.search).get('lang')||localStorage.getItem('idioma')}catch(e){}
  if(!IDIOMAS[l])l=(navigator.languages||[navigator.language]).map(x=>IDIOMAS[x]?x:/^pt-pt/i.test(x)?'pt':/^pt/i.test(x)?'pt-BR':x.slice(0,2).toLowerCase()).find(x=>IDIOMAS[x])||'es';
  if(fija){
    /* Solo desde la versión en español: si el visitante prefiere otro idioma, se le lleva a su versión. Los buscadores no se redirigen. */
    if(fija==='es'&&l!=='es'&&!/bot|crawl|spider|slurp|lighthouse/i.test(navigator.userAgent)){location.replace(urlDe(l));return}
    l=fija;
  }
  aplicar(l);
})();
